// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Read-only page capture for fixtures: accessibility tree + text, redacted
// Flo: open the page (halt checks apply) > read url, language, text, accessibility names > redact private bits > write JSON in stat/snaps
// I/O: path or url + name (caller) > <stat>/snaps/<name>.json (redacted, outside the repo); never clicks, never types
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const priv = @import("ru-safe-priv.zig");
const CF = .{ .dir = "snaps", .maxn = 800, .lang = "document.documentElement.lang||''" };
pub const AxRow = struct { r: []const u8, n: []const u8 };
pub const Snap = struct { url: []const u8, lang: []const u8, text: []const u8, ax: []const AxRow };
pub fn safeName(aren: std.mem.Allocator, name: []const u8) ![]u8 { const out = try aren.alloc(u8, @max(name.len, 1)); if (name.len == 0) { out[0] = 'x'; return out; } for (name, 0..) |chr, ix| out[ix] = if (std.ascii.isAlphanumeric(chr) or chr == '-' or chr == '_') std.ascii.toLower(chr) else '_'; return out; }
pub fn redactUrl(aren: std.mem.Allocator, urlz: []const u8) ![]u8 { const cut = std.mem.findScalar(u8, urlz, '?') orelse urlz.len; var out: std.ArrayList(u8) = .empty; const src = urlz[0..cut]; var idx: usize = 0; while (idx < src.len) { if (src[idx] >= '0' and src[idx] <= '9') { var end = idx; while (end < src.len and src[end] >= '0' and src[end] <= '9') end += 1; if (end - idx >= 6) { try out.append(aren, '#'); } else { try out.appendSlice(aren, src[idx..end]); } idx = end; } else { try out.append(aren, src[idx]); idx += 1; } } return out.items; }
fn axRows(ctx: *task.Ctx) ![]const AxRow { ctx.page.arm(ctx.conf.brow_time_seco * 1000); const res = try ctx.page.call(ctx.aren, "Accessibility.getFullAXTree", ""); const nodes = res.object.get("nodes") orelse return error.CdpError; var out: std.ArrayList(AxRow) = .empty; for (nodes.array.items) |nod| { if (out.items.len >= CF.maxn) break; if (nod != .object) continue; if (nod.object.get("ignored")) |ign| { if (ign == .bool and ign.bool) continue; } const nam = valOf(nod.object.get("name")); if (nam.len == 0) continue; try out.append(ctx.aren, .{ .r = valOf(nod.object.get("role")), .n = try priv.redact(ctx.aren, nam) }); } return out.items; }
fn valOf(valu: ?std.json.Value) []const u8 { const vv = valu orelse return ""; if (vv != .object) return ""; const inn = vv.object.get("value") orelse return ""; return if (inn == .string) inn.string else ""; }
pub fn capture(ctx: *task.Ctx, target: []const u8, name: []const u8) ![]const u8 { try task.visit(ctx, target); ctx.page.arm(ctx.conf.brow_time_seco * 1000); const urlz = try ctx.page.urlNow(ctx.aren); const lang = ctx.page.evalStr(ctx.aren, CF.lang) catch ""; const txt = try ctx.page.textNow(ctx.aren); const snp: Snap = .{ .url = try redactUrl(ctx.aren, urlz), .lang = lang, .text = try priv.redact(ctx.aren, txt), .ax = try axRows(ctx) }; const body = try std.json.Stringify.valueAlloc(ctx.aren, snp, .{}); const dir = try std.fs.path.join(ctx.aren, &.{ ctx.statd, CF.dir }); try std.Io.Dir.cwd().createDirPath(ctx.iozz, dir); const file = try std.fmt.allocPrint(ctx.aren, "{s}.json", .{try safeName(ctx.aren, name)}); const path = try std.fs.path.join(ctx.aren, &.{ dir, file }); try std.Io.Dir.cwd().writeFile(ctx.iozz, .{ .sub_path = path, .data = body }); task.say(ctx, "saved {s} ({d} names)", .{ path, snp.ax.len }); return path; }
